WITH filtered AS (SELECT *, CASE WHEN job_title = 'Analyst' THEN 1 ELSE 0 END is_analyst, COALESCE(level, 'OTHER') level_clean FROM employees WHERE hire_date >= DATE '2023-06-09') SELECT level, COUNT_IF(job_title = 'Manager') AS manager_events, SUM(CASE WHEN job_title = 'Analyst' THEN is_analyst ELSE 0 END) AS analyst_is_analyst, PERCENTILE_APPROX(is_analyst, ARRAY(0.25, 0.5, 0.75)) AS is_analyst_quartiles, GROUPING(level) AS grouping_level FROM filtered GROUP BY ROLLUP (level) ORDER BY analyst_is_analyst ASC
